// Level a gym leader's team is built at (0-indexed gym).
export function gymLevel(region, gymIndex) {
  return region.startLevel + 7 + gymIndex * 6; // 12, 18, ... 54
}
export function eliteLevel(region, eliteIndex) {
  return 56 + eliteIndex * 2; // 56, 58, 60, 62
}
export function championLevel() {
  return 66;
}
// Rough wild level for the leg leading up to a given gym. Tracks the player's
// expected level (a gentle curve from the starter level) rather than the gym's,
// so early wilds stay fair for a small low-level team.
export function wildLevelForLeg(region, gymIndex, rng) {
  const target = region.startLevel + gymIndex * 6;
  return Math.max(2, target + rng.int(-2, 1));
}

// Map shape per leg (rows of branching nodes before the gym).
export const MAP_SHAPE = { rows: 4, minPerRow: 2, maxPerRow: 3 };
